import{_ as a,o,c as i,a7 as n}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"LocalTell Privacy Policy","description":"Official Privacy Policy for LocalTell.","frontmatter":{"title":"LocalTell Privacy Policy","description":"Official Privacy Policy for LocalTell.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/local-tell.md","filePath":"privacy/local-tell.md"}'),r={name:"privacy/local-tell.md"};function t(l,e,s,c,d,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="privacy-policy-for-localtell" tabindex="-1">Privacy Policy for LocalTell <a class="header-anchor" href="#privacy-policy-for-localtell" aria-label="Permalink to &quot;Privacy Policy for LocalTell&quot;">​</a></h1><p><strong>Effective Date:</strong> September 24, 2026<br><strong>Last Updated:</strong> September 24, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>LocalTell is an offline-first Android app developed by <strong>Anand Raja</strong>. It uses serving cellular network identifiers to estimate an approximate locality from an offline data pack installed on your device. It has no account, advertising, analytics, tracking, or developer-operated cloud service.</p><h2 id="information-processed-on-your-device" tabindex="-1">Information processed on your device <a class="header-anchor" href="#information-processed-on-your-device" aria-label="Permalink to &quot;Information processed on your device&quot;">​</a></h2><p>After you grant Android&#39;s location permission, LocalTell can read registered serving-cell information supplied by Android: radio technology, mobile country code, mobile network code, area code, cell identifier, and signal strength. It uses this information locally to match an approximate area in a downloaded offline SQLite pack.</p><p>LocalTell does not request or read GPS coordinates. Android treats access to cell identifiers as location-sensitive, which is why Android requires location permission before it exposes this information.</p><p>If you use Journey mode, LocalTell stores a local history of approximate-area matches. An entry includes its timestamp, approximate area, optional district and state, radio technology, network code, cell identifier, and confidence. Offline pack preferences and installed-pack metadata are also kept in app-private storage.</p><h2 id="network-use-and-offline-packs" tabindex="-1">Network use and offline packs <a class="header-anchor" href="#network-use-and-offline-packs" aria-label="Permalink to &quot;Network use and offline packs&quot;">​</a></h2><p>Internet access is used only to retrieve the published offline-pack manifest, download a pack you choose, and periodically check for pack updates. Pack URLs use HTTPS and downloaded packs are checked before use. Serving-cell data, Journey history, and approximate-area results are not sent to the developer as part of these requests.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>LocalTell may use the following Android permissions:</p><ul><li>Precise and approximate location permission, only so Android can provide serving cellular identifiers; LocalTell does not obtain GPS coordinates.</li><li>Internet permission for optional offline-pack downloads and update checks.</li><li>Foreground-service and foreground-service-location permissions for optional Journey mode, which periodically checks the serving cellular network while you have started the service.</li><li>Notification permission on Android versions that require it, only to show the ongoing Journey foreground-service notification.</li></ul><p>You can deny or revoke permissions in Android settings. Without location permission, LocalTell cannot read cell identifiers or resolve an approximate area. Journey mode requires cell access and, where applicable, notification permission.</p><h2 id="sharing-and-external-services" tabindex="-1">Sharing and external services <a class="header-anchor" href="#sharing-and-external-services" aria-label="Permalink to &quot;Sharing and external services&quot;">​</a></h2><p>When you choose Share, LocalTell places a sentence containing the approximate area result into the Android share sheet. The app or service you select handles that text under its own privacy policy. LocalTell does not automatically share results.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and deletion&quot;">​</a></h2><p>Data remains on your device until you remove it. You can remove an installed offline pack in the Offline data screen and clear Journey history in the Journey screen. Clearing LocalTell&#39;s storage in Android settings or uninstalling LocalTell removes its app-private data, including downloaded packs and Journey history. Android backup and device-transfer rules exclude LocalTell app data.</p><p>The developer does not hold an account or cloud copy of this data, so there is no developer-held app data to delete by email. Support email contains only the information you choose to send.</p><h2 id="children-s-privacy-and-policy-changes" tabindex="-1">Children&#39;s privacy and policy changes <a class="header-anchor" href="#children-s-privacy-and-policy-changes" aria-label="Permalink to &quot;Children&#39;s privacy and policy changes&quot;">​</a></h2><p>LocalTell is not designed to collect children&#39;s personal information through a developer-operated service. This policy may change if the app&#39;s features or data practices change; the dates above will be updated when a revised policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',23)])])}const u=a(r,[["render",t]]);export{f as __pageData,u as default};
